function groupSign(amount, currency, group) {
  const decimals = minorUnitDigits(currency);
  const perMajor = 10 ** decimals;
  const absolute = Math.abs(amount);
  const major = Math.floor(absolute / perMajor);
  const minor = absolute % perMajor;
  const sign = amount < 0 ? '-' : '';
  const fraction = decimals === 0 ? '' : `.${String(minor).padStart(decimals, '0')}`;
  return `${sign}${group(String(major))}${fraction}`;
}

