import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  billingPeriods,
  buildInvoice,
  createBook,
  createCatalog,
  defineCoupon,
  definePlan,
  defineTaxTable,
  formatAmount,
  parseAmount,
  sumAmounts,
} from '../src/index.mjs';
import { makeBook, subscribeTo } from './support/world.mjs';

test('renewals stay on the anchor day after a short month', () => {
  assert.deepEqual(
    billingPeriods('2023-01-31', 1, 4).map((period) => period.end),
    ['2023-02-28', '2023-03-31', '2023-04-30', '2023-05-31'],
  );
  assert.equal(billingPeriods('2023-11-30', 3, 3)[1].start, '2024-02-29');
});

test('amounts follow the currency decimals', () => {
  assert.equal(parseAmount('2900', 'JPY'), 2900);
  assert.equal(parseAmount('9.995', 'KWD'), 9995);
  assert.throws(() => parseAmount('29.00', 'JPY'), RangeError);
  assert.equal(formatAmount(9995, 'KWD'), 'KWD 9.995');
});

test('the day of a change is billed at the new price', () => {
  const plan = (code, price) => definePlan({ code, prices: { USD: price } });
  const book = createBook({ catalog: createCatalog([plan('a', '29.00'), plan('b', '58.00')]) });
  book.subscribe({ id: 's', customerId: 'c', planCode: 'a', currency: 'USD', anchor: '2024-02-01' });
  const invoice = book.changePlan('s', { date: '2024-02-16', planCode: 'b' });
  assert.deepEqual(invoice.lines.map((line) => line.amount), [-1400, 2800]);
});

test('a change on a discounted subscription never gives back more than was paid', () => {
  const book = makeBook();
  subscribeTo(book, { couponCode: 'WELCOME', region: null });
  const change = book.changePlan('sub_1', { date: '2024-04-01', planCode: 'business' });
  assert.equal(change.lines[0].amount, -2700);
  assert.equal(change.lines[1].net, 5400);
  assert.equal(book.subscription('sub_1').couponUses, 1);
});

test('allocation is fair and mirrors negatives', () => {
  assert.deepEqual(allocate(1, [0, 1, 0]), [0, 1, 0]);
  assert.deepEqual(allocate(-5, [1, 1]), [-3, -2]);
  assert.equal(sumAmounts(allocate(9_000_000_000_001, [1, 1, 1])), 9_000_000_000_001);
});

test('line tax adds up to the invoice tax', () => {
  const invoice = buildInvoice({
    number: 'INV-1',
    customerId: 'c',
    currency: 'USD',
    issueDate: '2024-03-01',
    lines: Array.from({ length: 5 }, (_, index) => ({
      description: `Seat ${index}`,
      unitAmount: 1005,
      taxRateBps: 1000,
    })),
  });
  assert.equal(sumAmounts(invoice.lines.map((line) => line.tax)), invoice.taxTotal);
  for (const line of invoice.lines) assert.ok(Math.abs(line.tax - line.net / 10) < 1);
});

test('account credit does not change the charge or the tax', () => {
  const book = makeBook();
  book.grantAccountCredit('cus_1', 'USD', { amount: 1000, date: '2024-03-01' });
  const invoice = subscribeTo(book);
  assert.equal(invoice.netTotal, 3000);
  assert.equal(invoice.taxTotal, 600);
  assert.equal(invoice.creditApplied, 1000);
  assert.equal(book.balanceOf(invoice.number), 2600);
});

test('staged credit notes end on a zero balance with the tax charged', () => {
  const book = makeBook();
  const invoice = subscribeTo(book, { seats: 3 });
  book.pay(invoice.number, { amount: invoice.total, date: '2024-04-02' });
  for (const amount of [1234, 2345]) {
    book.creditInvoice(invoice.number, { date: '2024-04-05', lines: [{ lineIndex: 0, amount }] });
  }
  book.creditInvoice(invoice.number, { date: '2024-04-06' });
  const notes = book.notesOn(invoice.number);
  assert.equal(sumAmounts(notes.map((note) => note.taxTotal)), invoice.taxTotal);
  assert.equal(sumAmounts(notes.map((note) => note.total)), invoice.total);
  assert.equal(book.balanceOf(invoice.number), 0);
  assert.deepEqual(book.unbalancedJournalEntries(), []);
});

test('cash refunds stop at the cash received', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.pay(invoice.number, { amount: 1000, date: '2024-04-02' });
  const note = book.creditInvoice(invoice.number, { date: '2024-04-05' });
  assert.deepEqual(note.settlement, { againstBalance: 2600, refunded: 1000, toAccount: 0 });
});

test('a credit note cannot repeat what a plan change already gave back', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.changePlan('sub_1', { date: '2024-04-01', planCode: 'business' });
  assert.deepEqual(book.remainingCreditable(invoice.number), [0]);
});

test('a plan change keeps a scheduled change', () => {
  const book = makeBook();
  subscribeTo(book);
  book.scheduleForRenewal('sub_1', { seats: 2 });
  book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.equal(book.subscription('sub_1').scheduled.seats, 2);
});

test('a failed request does not use up an invoice number', () => {
  const book = makeBook();
  subscribeTo(book);
  assert.throws(() => book.changePlan('sub_1', { date: '2024-06-01', seats: 2 }), RangeError);
  assert.equal(book.changePlan('sub_1', { date: '2024-04-10', seats: 2 }).number, 'INV-0002');
});

test('reports keep currencies apart', () => {
  const book = makeBook();
  subscribeTo(book, { region: null });
  subscribeTo(book, { id: 'sub_2', customerId: 'cus_2', currency: 'EUR', region: null });
  book.creditInvoice('INV-0002', { date: '2024-04-05' });
  assert.deepEqual(book.revenueByMonth('USD'), [{ month: '2024-04', amount: 3000 }]);
  assert.deepEqual(book.taxReport('USD', '2024-04'), [{ rateBps: 0, taxable: 3000, tax: 0 }]);
});
